function count_trailing_zeros_or_ones(val_64bit):
  lsb = val_64bit & 1
  cnt = 0
  for i from 0 to 63:
    if ((val_64bit >> i) & 1) == lsb:
      cnt = cnt + 1
    else:
      break
  res = cnt & 0x3F
  return res

function count_leading_zeros_or_ones(val_64bit):
  msb = (val_64bit >> 63) & 1
  cnt = 0
  for i from 63 down to 0:
    if ((val_64bit >> i) & 1) == msb:
      cnt = cnt + 1
    else:
      break
  res = cnt & 0x3F
  return res

function generate_digest(reg_type, val_64bit, fp_format = null):
  if reg_type == INT:
    trailing_cnt = count_trailing_zeros_or_ones(val_64bit) & 0x3F // 6 bits [5:0]
    leading_cnt  = count_leading_zeros_or_ones(val_64bit) & 0x3F  // 6 bits [8:3]
    lsb_6        = val_64bit & 0x3F                               // 6 bits [11:6]
    digest = trailing_cnt ^ (leading_cnt << 3) ^ (lsb_6 << 6)
    res = digest & 0xFFF // 12-bit digest
    return res
  else if reg_type == FP:
    // format classified from MSBs if not explicitly supplied
    if fp_format == null:
      if (val_64bit >> 16) == 0xFFFFFFFFFFFF:
        fp_format = FP16
      else if (val_64bit >> 32) == 0xFFFFFFFF or (val_64bit >> 32) == 0:
        fp_format = FP32
      else:
        fp_format = FP64
    if fp_format == FP16:
      res = ((val_64bit >> 13) & 0x7) << 3 // bits [5:3]
      return res
    else if fp_format == FP32:
      res = ((val_64bit >> 26) & 0x3F) << 3 // bits [8:3]
      return res
    else if fp_format == FP64:
      res = ((val_64bit >> 55) & 0x1FF) << 3 // bits [11:3]
      return res
  else if reg_type == FLAG:
    flag_4bit = val_64bit & 0xF
    res = (flag_4bit << 8) | (flag_4bit << 4) | flag_4bit // replicate 3 times: [11:8], [7:4], [3:0]
    return res
  return 0

function on_instruction_decoded(inst):
  // Invalidate stale digests after 256 subsequent decoded instructions
  for r in 0 .. 64:
    if Register_Status_Digest_Table[r].valid == 1:
      if Register_Status_Digest_Table[r].decay_ctr >= 255:
        Register_Status_Digest_Table[r].valid = 0
      else:
        Register_Status_Digest_Table[r].decay_ctr += 1

  // For instruction writing a destination register
  if inst.writes_register:
    dest_reg = inst.dest_logical_reg
    Register_Status_Digest_Table[dest_reg].valid = 0
    Register_Status_Digest_Table[dest_reg].payload = inst.rob_tag & 0x3FFF // 14-bit tag
    Register_Status_Digest_Table[dest_reg].decay_ctr = 0

function on_instruction_completed(inst, result_value):
  if inst.writes_register:
    dest_reg = inst.dest_logical_reg
    // Verify payload holds matching ROB tag to avoid overwriting newer instructions
    if Register_Status_Digest_Table[dest_reg].valid == 0 and Register_Status_Digest_Table[dest_reg].payload == (inst.rob_tag & 0x3FFF):
      digest = generate_digest(inst.reg_type, result_value)
      Register_Status_Digest_Table[dest_reg].payload = digest & 0xFFF // store 12-bit digest
      Register_Status_Digest_Table[dest_reg].decay_ctr = 0
      Register_Status_Digest_Table[dest_reg].valid = 1

